do $patch$ declare definition text; begin select pg_get_functiondef('public.odap_rpc(text,text,text,text,jsonb)'::regprocedure) into definition; definition:=replace(definition,$old$select to_jsonb(p) into result from public.odap_packets p where id=(p_payload->>'id')::uuid;return result;$old$,$new$select case when p_payload->>'metadata_only'='true' then to_jsonb(p)-'body' else to_jsonb(p) end into result from public.odap_packets p where id=(p_payload->>'id')::uuid;return result;$new$); execute definition;end $patch$;